root_path = fileparts(mfilename("fullpath"));
root_path  = pwd;
data_path = fullfile(root_path,'sym4D_cutsAndFits');

if ~exist('cuts2fit400','var')
    ld = load(fullfile(data_path,'multicuts_fit_dataGH_ei400meV.mat'));
    cuts2fit400 = ld.cuts2fit400;
end
if exist('used_ds400','var') %[output:group:4503f99c]
    used_ds   = used_ds400;
else
    used_ds = containers.Map() %[output:588e928d]
    sel_info = struct('cuts',[],'en_range',[],'fname','','bg_par',[]);
    %
    sel_info.cuts = cuts2fit400.cuts_dir001FFfit(1);
    sel_info.en_range = 50:10:160;
    sel_info.cut_dim  = 2;
    sel_info.fname='EnFit_Ei400ref001off110_2D_constFFCut';
    sel_info.bg_par= {};
    used_ds('Ei400Br110dir001')=sel_info;
    %
    sel_info.cuts = cuts2fit400.cuts_dir001FFfit(2);
    sel_info.en_range = 50:10:200;
    sel_info.cut_dim  = 2;
    sel_info.fname='EnFit_Ei400ref001off200_2D_constFFCut';
    sel_info.bg_par= {};
    used_ds('Ei400Br200dir001')=sel_info;

    %
    sel_info.cuts = cuts2fit400.cuts_dir001FFfit(1);
    sel_info.en_range = 50:10:160;
    sel_info.cut_dim  = 1;
    sel_info.fname='EnFit_Ei400ref001off110_1D_constFFCut';
    sel_info.bg_par= {};
    used_ds('Ei400Br110dir001_1D')=sel_info;
    %
    sel_info.cuts = cuts2fit400.cuts_dir001FFfit(2);
    sel_info.en_range = 50:10:200;
    sel_info.cut_dim  = 1;
    sel_info.fname='EnFit_Ei400ref001off200_1D_constFFCut';
    sel_info.bg_par= {};
    used_ds('Ei400Br200dir001_1D')=sel_info;
    used_ds400 = used_ds;
end %[output:group:4503f99c]
%%


%cuts_list = cuts2fit400.cutsS_list; % all available cuts
%cuts_list = {cuts2fit400.cut_b200_200sel}; % cuts in low ff direction arount <200>
%cuts_list = cuts2fit400.cuts_dir001FFfit(1);
select= 'Ei400Br110dir001_1D';
sel_info = used_ds(select);

cuts_list = sel_info.cuts;

mi = maps_instrument(400,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for i=1:numel(cuts_list) %[output:group:759e13b7]
    cuts_list{i} = cuts_list{i}.set_instrument(mi);
    cuts_list{i} = cuts_list{i}.set_sample(sample);
    plot(cuts_list{i}); lz 0 1; keep_figure; %[output:757a55c6]
end %[output:group:759e13b7]


dir_name  = "GH";

dE_step = 4; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning
%cut_en = 50:10:260;
%cut_en = 50:10:160; %cuts2fit400.cuts_dir001FFfit(1);
cut_en = sel_info.en_range; %cuts2fit400.cuts_dir001FFfit(2);
cut_dimensions = sel_info.cut_dim;

%cl= {cuts_list{3}};
%cl = {w2_test_cut};
% if isfield(cuts2fit400,'bg_par_010off000')
%     if numel(cuts_list) == 3
%         bg_par = {cuts2fit400.bg_par_010off000.p,cuts2fit400.bg_par_010off100.p,cuts2fit400.bg_par_010off200.p};
%     else
%         bg_par  = {cuts2fit400.bg_par_010off100.p};
%     end
%     cuts_list{end+1} = bg_par;
% end
bg_par = sel_info.bg_par;
cuts_list{end+1} = bg_par;
fbase_name  = sel_info.fname;
%%


[fit_res_400rec,res_name] = fit_multicuts_along_direction(... %[output:group:763bcccf] %[output:8b7a3626] %[output:5ff8fecd] %[output:376dc27e] %[output:9b62a27f] %[output:8031f615] %[output:70f9cc51] %[output:4c05e6d8] %[output:4e7c85af] %[output:39282db4] %[output:14df2380] %[output:85859873] %[output:7f7016e7] %[output:01aa374e] %[output:1b5ac2bd] %[output:6c542b36] %[output:81eb2425] %[output:84303ec5] %[output:7cfe7c89] %[output:467b8efc] %[output:54b3b11f] %[output:72a408e0] %[output:0193b8fe] %[output:978ee7c9] %[output:7fe397ea] %[output:8c05ebc9] %[output:960c8c09] %[output:8ac5b6aa] %[output:162d3f08] %[output:3c889de5] %[output:6eee3463] %[output:57849223] %[output:04ee9ea4] %[output:83d9b344] %[output:5504880d] %[output:7c40cb45] %[output:2e4efd30] %[output:66e9dc4d] %[output:5333a45f] %[output:25f183cc] %[output:5dc349e4] %[output:777a317a] %[output:80774956] %[output:651b2fc4] %[output:36b9a464] %[output:341fd92f] %[output:04e91404] %[output:2fa07831] %[output:264e0819] %[output:3328575a] %[output:89c53b92]
    cuts_list,fbase_name,dir_name,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:763bcccf] %[output:8b7a3626] %[output:5ff8fecd] %[output:376dc27e] %[output:9b62a27f] %[output:8031f615] %[output:70f9cc51] %[output:4c05e6d8] %[output:4e7c85af] %[output:39282db4] %[output:14df2380] %[output:85859873] %[output:7f7016e7] %[output:01aa374e] %[output:1b5ac2bd] %[output:6c542b36] %[output:81eb2425] %[output:84303ec5] %[output:7cfe7c89] %[output:467b8efc] %[output:54b3b11f] %[output:72a408e0] %[output:0193b8fe] %[output:978ee7c9] %[output:7fe397ea] %[output:8c05ebc9] %[output:960c8c09] %[output:8ac5b6aa] %[output:162d3f08] %[output:3c889de5] %[output:6eee3463] %[output:57849223] %[output:04ee9ea4] %[output:83d9b344] %[output:5504880d] %[output:7c40cb45] %[output:2e4efd30] %[output:66e9dc4d] %[output:5333a45f] %[output:25f183cc] %[output:5dc349e4] %[output:777a317a] %[output:80774956] %[output:651b2fc4] %[output:36b9a464] %[output:341fd92f] %[output:04e91404] %[output:2fa07831] %[output:264e0819] %[output:3328575a] %[output:89c53b92]
%cl,'En_cuts800',dir_name,cut_en,dE_step,half_dE);
beep
beep
beep

%%
fit_res_400 = fit_res_400rec;

bg_data = extract_bg_par(fit_res_400.all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(fit_res_400.all_fit_par(1).en,fit_res_400.all_fit_par(end).en);keep_figure; %[output:7b4c1f29]
pd(bg_data(2));lx(fit_res_400.all_fit_par(1).en,fit_res_400.all_fit_par(end).en);keep_figure %[output:7bfbbd63]
%%
fit_resEi400 = fit_res_400rec;
save(res_name,"fit_resEi400")

